// Whether `&` in a title marks a mnemonic that selects the page (on for strips; the document preset turns it off, DK-38). When off, a title is shown as written.
template <typename Declaring>
struct PageStripMnemonicsEnabledCapability {
    PropertyCell<bool, PageStripMnemonicsEnabledCapability<Declaring>> mnemonics_enabled{true};

    static void assign(PageStripMnemonicsEnabledCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.mnemonics_enabled), incoming);
        if (!capability.mnemonics_enabled.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.mnemonics_enabled));
    }
};

// Whether an unclaimed drag reorders tabs live (owner decision DK-39): off by default, the strip preset; PageView's document preset turns it on. Turning it off cancels a drag under way.
template <typename Declaring>
struct PageStripReorderEnabledCapability {
    PropertyCell<bool, PageStripReorderEnabledCapability<Declaring>> reorder_enabled{};

    static void assign(PageStripReorderEnabledCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.reorder_enabled), incoming);
        if (!capability.reorder_enabled.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.reorder_enabled));
    }
};

// The images a page's `image_key` names, or null. A disposed list or one belonging to another window throws std::invalid_argument.
template <typename Declaring>
struct PageStripImageListCapability {
    PropertyCell<std::shared_ptr<ImageList>, PageStripImageListCapability<Declaring>> image_list{};

    static void assign(PageStripImageListCapability& capability, std::shared_ptr<ImageList> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.image_list), incoming);
        if (!capability.image_list.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.image_list));
    }
};

// Content-only owner drawing (owner decision W-Q6; TabControl's OwnerDrawFixed with DrawItem): in owner_draw the strip raises draw_item_content for each painted tab's content; the plate, close button, pin, modified mark and focus cue stay painted by role. An unknown mode throws std::invalid_argument.
template <typename Declaring>
struct PageStripDrawModeCapability {
    PropertyCell<ItemDrawMode, PageStripDrawModeCapability<Declaring>> draw_mode{ItemDrawMode::normal};

    static void assign(PageStripDrawModeCapability& capability, ItemDrawMode incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.draw_mode), incoming);
        if (!capability.draw_mode.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.draw_mode));
    }
};

// Every PageStrip capability, in the order the declaring class takes them.
template <typename Declaring>
struct PageStripCapabilities : public PageStripPlacementPropertyCapability<Declaring>,
                               public PageStripItemSizingCapability<Declaring>,
                               public PageStripItemWidthsCapability<Declaring>,
                               public PageStripActivationPropertyCapability<Declaring>,
                               public PageStripOverflowPropertyCapability<Declaring>,
                               public PageStripCloseButtonsCapability<Declaring>,
                               public PageStripMnemonicsEnabledCapability<Declaring>,
                               public PageStripReorderEnabledCapability<Declaring>,
                               public FontCapability<Declaring>,
                               public PageStripImageListCapability<Declaring>,
                               public PageStripDrawModeCapability<Declaring> {
    PageStripCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::control, 10.5, 400, false, 0.12}) {}
};

